import{_ as p,a0 as l,w as r,s as o,ao as h,I as n,x as a,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"Bash 基础知识系列 #6：处理字符串操作 | LCTT x X-CMD","titleTemplate":false,"description":"Bash 基础知识系列 #6：处理字符串操作 | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bash 基础知识系列 #6：处理字符串操作 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bash 基础知识系列 #6：处理字符串操作 | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230717.0 ⭐️⭐️ Bash Basics Series 6 Handling String Operations","title":"Bash 基础知识系列 #6：处理字符串操作","tag":"202307","desc":""},"relativePath":"202307/20230717.0 ⭐️⭐️ Bash Basics Series 6 Handling String Operations.md","filePath":"[post].md"}'),d={name:"202307/20230717.0 ⭐️⭐️ Bash Basics Series 6 Handling String Operations.md"};function g(b,s,c,u,k,m){const t=l("Link");return r(),o("div",null,[s[15]||(s[15]=h(`<h1 id="bash-基础知识系列-6-处理字符串操作" tabindex="-1">Bash 基础知识系列 #6：处理字符串操作 <a class="header-anchor" href="#bash-基础知识系列-6-处理字符串操作" aria-label="Permalink to “Bash 基础知识系列 #6：处理字符串操作”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202307/30/090030gvm6pgutlvzll4zg.jpg" alt=""></p><p>在大多数编程语言中，你都会找到字符串数据类型。字符串基本上是一组字符。</p><p>但 Bash shell 有所不同。字符串没有单独的数据类型。这里一切都是变量。</p><p>但这并不意味着你不能像在 C 和其他编程语言中那样处理字符串。</p><p>在 Bash Shell 中可以查找子字符串、替换子字符串、连接字符串以及更多字符串操作。</p><p>在 Bash 基础知识系列的这一部分中，你将学习基本的字符串操作。</p><h3 id="在-bash-中获取字符串长度" tabindex="-1">在 Bash 中获取字符串长度 <a class="header-anchor" href="#在-bash-中获取字符串长度" aria-label="Permalink to “在 Bash 中获取字符串长度”">​</a></h3><p>让我们从最简单的选项开始。也就是获取字符串的长度。这很简单：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\${#string}</span></span></code></pre></div><p>让我们在示例中使用它。</p><p><img src="https://itsfoss.com/content/images/2023/07/bash-string-length-example.png" alt="Example of getting string length in bash"></p><p>正如你所看到的，第二个示例中有两个单词，但由于它用引号引起来，因此它被视为单个单词。连空格都算作一个字符。</p><h3 id="在-bash-中连接字符串" tabindex="-1">在 Bash 中连接字符串 <a class="header-anchor" href="#在-bash-中连接字符串" aria-label="Permalink to “在 Bash 中连接字符串”">​</a></h3><p>用技术术语来说是字符串 <ruby>连接<rt>concatenation</rt></ruby>，这是 Bash 中最简单的字符串操作之一。</p><p>你只需像这样一个接一个地使用字符串变量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>str3=$str1$str2</span></span></code></pre></div><p>还能比这更简单吗？我觉得不能。</p><p>让我们看一个例子。这是我的示例脚本，名为 <code>join.sh</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>read -p &quot;Enter first string: &quot; str1</span></span>
<span class="line"><span>read -p &quot;Enter second string: &quot; str2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>joined=$str1$str2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;The joined string is: $joined&quot;</span></span></code></pre></div><p>以下是该脚本的运行示例：</p><p><img src="https://itsfoss.com/content/images/2023/07/join-strings-bash.png" alt="Join two strings in bash"></p><h3 id="在-bash-中提取子字符串" tabindex="-1">在 Bash 中提取子字符串 <a class="header-anchor" href="#在-bash-中提取子字符串" aria-label="Permalink to “在 Bash 中提取子字符串”">​</a></h3><p>假设你有一个包含多个字符的大字符串，并且你想要提取其中的一部分。</p><p>要提取子字符串，需要指定主字符串、子字符串的起始位置和子字符串的长度，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\${string:$pos:$len}</span></span></code></pre></div><blockquote><p>💡 和数组一样，字符串中的定位也是从 0 开始。</p></blockquote><p>这是一个例子：</p><p><img src="https://itsfoss.com/content/images/2023/07/extract-substring-bash.png" alt="Extracting substring in bash"></p><p>即使你指定的子字符串长度大于字符串长度，它也只会到达字符串末尾。</p><h3 id="替换-bash-中的子字符串" tabindex="-1">替换 Bash 中的子字符串 <a class="header-anchor" href="#替换-bash-中的子字符串" aria-label="Permalink to “替换 Bash 中的子字符串”">​</a></h3><p>假设你有一个大字符串，并且你想用另一个字符串替换其中的一部分。</p><p>在这种情况下，你可以使用这种语法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\${string/substr1/substr2}</span></span></code></pre></div><blockquote><p>✋ 只有第一次出现的子字符串才会以这种方式替换。如果要替换所有出现的地方，请使用 <code>\${string//substr1/substr2}</code></p></blockquote><p>这是一个例子：</p><p><img src="https://itsfoss.com/content/images/2023/07/replace-substring-bash.png" alt="Replace substring in bash"></p><p>正如你在上面看到的，“good” 一词被替换为 “best”。我将替换的字符串保存到同一字符串中以更改原始字符串。</p><blockquote><p>💡 如果未找到子字符串，则不会替换任何内容。它不会导致错误。</p></blockquote><h3 id="在-bash-中删除子字符串" tabindex="-1">在 Bash 中删除子字符串 <a class="header-anchor" href="#在-bash-中删除子字符串" aria-label="Permalink to “在 Bash 中删除子字符串”">​</a></h3><p>我们来谈谈删除子字符串。假设你要删除字符串的一部分。在这种情况下，只需将子字符串提供给主字符串，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\${string/substring}</span></span></code></pre></div><blockquote><p>✋ 通过这种方式，仅删除第一次出现的子字符串。如果要删除所有出现的内容，请使用 <code>\${string//substr}</code></p></blockquote><p>如果找到子字符串，则将从字符串中删除它。</p><p>让我们通过一个例子来看看。</p><p><img src="https://itsfoss.com/content/images/2023/07/bash-delete-substring.png" alt="Delete substring in bash"></p><p>不用说，如果没有找到子字符串，则不会删除它。它不会导致错误。</p><h3 id="🏋️-练习时间" tabindex="-1">🏋️ 练习时间 <a class="header-anchor" href="#🏋️-练习时间" aria-label="Permalink to “🏋️ 练习时间”">​</a></h3><p>现在是你通过简单练习来实践字符串操作的时候了。</p><p><strong>练习 1</strong>：声明一个字符串 “I am all wet”。现在通过用 “set” 替换单词 “wet” 来更改此字符串。</p><p><strong>练习 2</strong>：创建一个字符串，以 <code>112-123-1234</code> 格式保存电话号码。现在，你必须删除所有 <code>-</code>。</p><p>这应该会给你一些在 Bash 中使用字符串的不错的练习。在下一章中，你将学习如何在 Bash 中使用 <code>if-else</code> 语句。敬请关注。</p><p><em>（题图：MJ/aa73b2c9-6d2f-42e2-972d-94fab56d30cc）</em></p><hr>`,54)),n("p",null,[s[1]||(s[1]=a("via: ",-1)),e(t,{href:"https://itsfoss.com/bash-strings/"},{default:i(()=>[...s[0]||(s[0]=[a("https://itsfoss.com/bash-strings/",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=a("作者：",-1)),e(t,{href:"https://itsfoss.com/author/abhishek/"},{default:i(()=>[...s[2]||(s[2]=[a("Abhishek Prakash",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(t,{href:"https://github.com/lkxed/"},{default:i(()=>[...s[3]||(s[3]=[a("lkxed",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(t,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(t,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const C=p(d,[["render",g]]);export{x as __pageData,C as default};
